## Code Example
```javascript
function shouldBatch(now, lastSent, urgency, dnd) {
  if (urgency === 'urgent') return false;
  if (dnd) return true;
  const withinWindow = (now - lastSent) < 15*60*1000;
  return withinWindow;
}
```

